INSERT INTO DevotionDay VALUES('bfa6fc60-8a94-4433-9a51-276da55b7d2d','4cc247ae-46ef-479f-a107-17fb497303bc',1,'The Purpose of Trials','Trials are not meant to destroy you but to refine you. Just as gold is tried in the fire, your faith is purified when subjected to the heat of life''s challenges.','https://images.unsplash.com/photo-1504052434569-70ad5836ab65?auto=format&fit=crop&w=800&q=80',20,0,1783415690302,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('501c3a75-921a-4a57-9a45-178cbb8fa65a','4cc247ae-46ef-479f-a107-17fb497303bc',2,'Anchored in the Word','When the winds of adversity blow, only those anchored in the Word of God will remain steadfast. Let the scripture be your ultimate reality.','https://images.unsplash.com/photo-1504052434569-70ad5836ab65?auto=format&fit=crop&w=800&q=80',20,0,1783415690302,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('bdeab991-7769-4591-8459-5b6a802218b1','4cc247ae-46ef-479f-a107-17fb497303bc',3,'The Shield of Faith','Faith is your shield against the fiery darts of the enemy. It is a deliberate choice to trust God''s character even when you cannot trace His hand.','https://images.unsplash.com/photo-1504052434569-70ad5836ab65?auto=format&fit=crop&w=800&q=80',20,0,1783415690302,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('39aeaa4c-db8e-4c8b-a18d-e5f4a2c78037','4cc247ae-46ef-479f-a107-17fb497303bc',4,'Patience in the Process','God is never in a hurry, but He is always on time. Embrace the process and let patience have its perfect work in your life.','https://images.unsplash.com/photo-1504052434569-70ad5836ab65?auto=format&fit=crop&w=800&q=80',20,0,1783415690302,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('db4ac345-9c20-4d49-8bcd-39ccba269986','4cc247ae-46ef-479f-a107-17fb497303bc',5,'Emerging Victorious','You will come out of this fire without the smell of smoke. The same situation meant to break you will be the testimony of your rising.','https://images.unsplash.com/photo-1504052434569-70ad5836ab65?auto=format&fit=crop&w=800&q=80',20,0,1783415690302,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('4bf98339-1628-4d3d-a7eb-dd3370572830','54a04e8c-5b02-4f74-b57e-a83d32f623ab',1,'The Mind of a Leader','Leadership begins in the mind. You cannot lead people to a place you have not visited in your imagination and thinking.','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80',25,0,1783415690340,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('4527d9a3-b704-4edf-983c-06c3d41ab0b7','54a04e8c-5b02-4f74-b57e-a83d32f623ab',2,'Service Above Self','True leadership is not about being served but about serving others. The greatest among you must be a servant.','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80',25,0,1783415690340,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('f14e40a3-363f-448f-97fd-217116dbb03c','54a04e8c-5b02-4f74-b57e-a83d32f623ab',3,'Empowering Others','A successful leader is one who reproduces their success in others. Your legacy is measured by the leaders you leave behind.','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80',25,0,1783415690340,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('95eca043-d7ed-41a2-a2bb-bdf682de17d2','596b09a2-733c-4be5-b538-3f8a584bf652',1,'Love Defined','God is love. To know God is to know love. We cannot claim to follow Him if our lives do not reflect His unconditional love.',NULL,20,0,1783415690347,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('0ed968f5-4521-4bf3-abbb-832f3ea0f2b8','596b09a2-733c-4be5-b538-3f8a584bf652',2,'Love in Action','Love is patient, love is kind. It does not envy, it does not boast. Action validates the authenticity of our love.',NULL,20,0,1783415690347,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('97d0295c-a594-4e59-9e1f-b3fe1b189cbb','596b09a2-733c-4be5-b538-3f8a584bf652',3,'Love Conquers All','Perfect love casts out fear. When you operate in the love of Christ, every fear of tomorrow or failure is eradicated.',NULL,20,0,1783415690347,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('958949d6-0f0c-46fe-aa4b-bb08e5a374c6','07ee32c7-b34b-4e43-8608-50ac5181ff62',1,'The Purpose of Trials','Trials are not meant to destroy you but to refine you. Just as gold is tried in the fire, your faith is purified when subjected to the heat of life''s challenges. God uses difficult seasons to strip away self-dependence, forcing us to lean entirely on His grace. When you find yourself in the furnace of affliction, remember that the Master Craftsman is watching closely, adjusting the temperature to ensure that your character emerges flawless, lacking nothing, and perfectly prepared for the next level of your assignment.','https://images.unsplash.com/photo-1469122312224-c5846569feb1?auto=format&fit=crop&w=800&q=80',20,0,1783951782928,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('450c7f2b-db15-43cd-a9c6-9a61ea8e1247','07ee32c7-b34b-4e43-8608-50ac5181ff62',2,'Anchored in the Word','When the winds of adversity blow, only those anchored deep in the Word of God will remain steadfast. Let the scripture be your ultimate reality, overriding the facts of your temporary situation. To be anchored means your emotional state, decisions, and confessions are not subject to the chaotic updates of this world. When you meditate on the Word day and night, you build a structural system within your spirit that cannot be shaken by financial storms, health challenges, or relational breakdowns.','https://images.unsplash.com/photo-1528644318721-c4fc8286a111?auto=format&fit=crop&w=800&q=80',20,0,1783951782928,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('f3bfc0b9-c2fc-4b34-8b5b-c21e8626eefb','07ee32c7-b34b-4e43-8608-50ac5181ff62',3,'The Shield of Faith','Faith is your shield against the fiery darts of the enemy. It is a deliberate, active choice to trust God''s unwavering character even when you cannot trace His hand in your current circumstances. The enemy will throw arrows of doubt, anxiety, and fear, targeting your mind. By lifting the shield of faith—which is built through a track record of intimacy with God—you extinguish every single lie. You must declare what God has spoken, knowing that He is too faithful to fail and too wise to make a mistake.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',20,0,1783951782928,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('64f273cf-44a8-412f-9e8b-52856ff37863','07ee32c7-b34b-4e43-8608-50ac5181ff62',4,'Patience in the Process','God is never in a hurry, but He is always on time. Embrace the process and let patience have its perfect work in your life. The gap between the prophecy and the performance is called the process, and it is in this space that true spiritual stamina is formed. Do not try to bypass the wilderness, for it is the training ground for your destiny. Trust the timeline of God; he makes all things beautiful in its time, and those who wait upon Him will never be put to shame.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',20,0,1783951782928,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('f1378a2c-f8b9-4f28-8ed0-9fc2e92ffc84','07ee32c7-b34b-4e43-8608-50ac5181ff62',5,'Emerging Victorious','You will come out of this fire without the smell of smoke. The very situation that was orchestrated by the enemy to break your spirit will become the public testimony of your supernatural rising. God is turning your trial into a triumph and your mess into a timeless message. Stand firm and behold the salvation of the Lord. The storm you see today, you shall see no more forever, for your path is like the shining light that shines brighter and brighter unto the perfect day.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',20,0,1783951782928,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('f9a457c6-b098-44f7-acc1-fc02bcfec50e','0ac788a7-55e7-4343-a7a7-fda230b6e4b4',1,'The Mind of a Leader','Leadership begins in the mind. You cannot lead people to a place you have not visited first in your own imagination, vision, and thinking. A true leader must break free from past limitations, paradigms of lack, and cultural constraints to see things from a dimension of possibilities. Your leadership capacity is strictly defined by your mental model. Spend time upgrading your mind through strategic learning, meditation on global principles, and listening to the blueprint of heaven for your generation.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',25,0,1783951782976,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('3d06d37b-91db-4f0b-9dc2-968f63edf60c','0ac788a7-55e7-4343-a7a7-fda230b6e4b4',2,'Service Above Self','True leadership is never about status, titles, or being served; it is entirely about serving others with excellence. The corporate world teaches power dynamics, but the kingdom teaches service dynamics. The greatest among you must be the servant of all. When your primary motivation shifts from personal gain to adding undeniable value to the lives of those you lead, you unlock a supernatural level of influence and respect that money cannot buy.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',25,0,1783951782976,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('9c15f919-9eda-4560-a8d9-4ca295d252d1','0ac788a7-55e7-4343-a7a7-fda230b6e4b4',3,'Empowering Others','A highly successful leader is one who reproduces their success, wisdom, and core values in others. Your ultimate legacy as a leader is not measured by the number of followers you gather, but by the quality of leaders you successfully train, develop, and leave behind. Shift your focus from personal performance to institutional mentorship. Build platforms that empower the next generation to stand on your shoulders and excel far beyond your reach.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',25,0,1783951782976,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('7c2d65ef-95f3-465d-81f4-336c89c7195c','43500925-e2fe-467e-a8fe-70523a78b07c',1,'Love Defined','God is love. To know God intimately is to know love in its purest, most unconditional form. We cannot validly claim to follow Him if our daily lives, speech, and interactions do not reflect His nature. This love is not a fleeting emotional feeling based on human performance, but a sovereign decision to seek the absolute best for others, regardless of how they treat us. Let your life be a living conduit of this refreshing, restorative grace.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',20,0,1783951782982,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('1b0ce21d-7f1f-4639-89fa-d6fb575ec75c','43500925-e2fe-467e-a8fe-70523a78b07c',2,'Love in Action','Love is patient, love is kind. It does not envy, it does not boast, and it keeps no record of wrongs. Daily action validates the authenticity of our love walk. It is easy to speak of love conceptually, but the true test comes when we are required to extend forgiveness to those who hurt us, feed those who cannot repay us, and show patience to the difficult people in our workspace. Let love be your highest priority and your primary operational framework today.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',20,0,1783951782982,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('ddbbf0c3-12e3-4af8-8a4c-371b8d39ddca','43500925-e2fe-467e-a8fe-70523a78b07c',3,'Love Conquers All','Perfect love completely casts out fear. When you actively operate in the unconditional love of Christ, every deep-seated fear of tomorrow, rejection, or failure is entirely eradicated from your heart. You are resting secure in the reality that your Heavenly Father deeply cares for you and protects you. Love is the most powerful spiritual force in the universe; it breaks down hardened walls, heals broken hearts, and guarantees final victory over every work of malice.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',20,0,1783951782982,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('dd9b79b9-43b2-49e2-aca5-ca036e7b124c','f78a2056-f00e-4b95-825f-a9a2bfc10a5a',1,'The Blueprint of Purpose','Before you were formed in your mother''s womb, God knew you, sanctified you, and ordained you for a specific purpose. True fulfillment in life cannot be found in material acquisition or public applause; it is found exclusively in discovering and executing the divine blueprint written concerning you in the books of heaven. Take time to strip away societal expectations and seek the Lord in prayer to clarify your specific calling and assignment for this season.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',30,0,1783951782988,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('8faf9cd3-e3d4-49fc-801a-1b4f3b779665','f78a2056-f00e-4b95-825f-a9a2bfc10a5a',2,'Supernatural Acceleration','When the hand of the Lord comes upon a man, he is empowered to outrun the chariots of Ahab. Divine speed is not a product of frantic human hustle or manipulation; it is the supernatural consequence of the Holy Spirit backing your life. God can compress time and compress seasons, giving you results in a single month that normally take men a decade to achieve. Align your heart with His will and watch Him accelerate your progress.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',30,0,1783951782988,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('a978ecc5-9774-4beb-b3c6-d8e38c8f1f4b','f78a2056-f00e-4b95-825f-a9a2bfc10a5a',3,'Eliminating Distractions','The enemy of great focus is not always bad things, but good things that have nothing to do with your current assignment. To experience true momentum and speed, you must learn to boldly say "No" to peripheral opportunities that drain your spiritual energy and time. Lay aside every weight and the sins that easily beset you, keeping your eyes completely fixed on the goal ahead. Streamline your routines, your circles, and your focus to match the magnitude of your vision.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',30,0,1783951782988,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('a6240220-4f26-48cd-aa1b-3a561b1d4024','f78a2056-f00e-4b95-825f-a9a2bfc10a5a',4,'The Power of Divine Alignment','Connection determines direction. Who you walk with, listen to, and submit to will drastically alter the speed of your destiny. Walking in alignment means partnering with the right spiritual cover, cultivating relationships with destiny helpers, and maintaining a pure posture before God. When your character aligns with heaven''s laws, structural blockages break away naturally, clearing a straight, highway-like path for your immediate elevation.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',30,0,1783951782988,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
INSERT INTO DevotionDay VALUES('332d04e3-f6fc-4ed0-9598-a1aa843192ae','f78a2056-f00e-4b95-825f-a9a2bfc10a5a',5,'Sustaining Momentum','Reaching a peak is one thing, but staying there requires a completely different level of spiritual discipline. To sustain the momentum of divine speed, your secret place of prayer, word study, and worship must remain completely non-negotiable. Success must never breed complacency or pride in your heart. Stay small in your own eyes, continuously give all the glory back to the Father, and remain a teachable vessel ready for the next instruction.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',30,0,1783951782988,'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4');
